mapper.select:
SELECT t.ID AS student_id, s.name, s.dept_name, s.tot_cred, t.grade
FROM takes t
JOIN student s ON t.ID = s.ID
WHERE t.course_id = #{courseId} AND t.sec_id = #{secId}
  AND t.semester = #{semester} AND t.year = #{year}
ORDER BY s.ID

SELECT COUNT(*)
FROM teaches
WHERE ID = #{instructorId} AND course_id = #{courseId}
  AND sec_id = #{secId} AND semester = #{semester} AND year = #{year}

mapper.update:
UPDATE takes
SET grade = #{grade}
WHERE ID = #{studentId} AND course_id = #{courseId}
  AND sec_id = #{secId} AND semester = #{semester} AND year = #{year}
